  Quote(id: 226, text: "Although the world is full of suffering, it is also full of the overcoming of it.", author: "Helen Keller", category: "Motivation"),
  Quote(id: 227, text: "A soft answer turneth away wrath: but grievous words stir up anger.", author: "Proverbs 15:1", category: "Bible"),
