  Quote(id: 229, text: "Courage is being afraid but going on anyhow.", author: "Dan Rather", category: "Fear"),
  Quote(id: 230, text: "Better is the end of a thing than the beginning thereof: and the patient in spirit is better than the proud in spirit.", author: "Ecclesiastes 7:8", category: "Bible"),
  Quote(id: 231, text: "O taste and see that the LORD is good: blessed is the man that trusteth in him.", author: "Psalms 34:8", category: "Bible"),
