  Quote(id: 287, text: "To love what you do and feel that it matters, how could anything be more fun?", author: "Katharine Graham", category: "Work"),
  Quote(id: 288, text: "Happiness consists more in small conveniences or pleasures that occur every day, than in great pieces of good fortune that happen but seldom.", author: "Benjamin Franklin", category: "Happiness"),
