  Quote(id: 344, text: "The LORD shall fight for you, and ye shall hold your peace.", author: "Exodus 14:14", category: "Bible"),
  Quote(id: 345, text: "For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.", author: "2 Timothy 1:7", category: "Bible"),
