  Quote(id: 351, text: "Happiness is not a matter of intensity but of balance, order, rhythm and harmony.", author: "Thomas Merton", category: "Happiness"),
  Quote(id: 352, text: "Whatever you do, do it well. Do it so well that when people see you do it, they will want to come back and see you do it again.", author: "Walt Disney", category: "Success"),
  Quote(id: 353, text: "Happiness quite unshared can scarcely be called happiness; it has no taste.", author: "Charlotte Bronte", category: "Happiness"),
  Quote(id: 354, text: "No man is free who is not master of himself.", author: "Epictetus", category: "Wisdom"),
  Quote(id: 355, text: "Believe you can and you're halfway there.", author: "Theodore Roosevelt", category: "Success"),
  Quote(id: 356, text: "It is not that we have a short time to live, but that we waste a lot of it.", author: "Seneca", category: "Wisdom"),
  Quote(id: 357, text: "Innovation distinguishes between a leader and a follower.", author: "Steve Jobs", category: "Success"),
  Quote(id: 358, text: "So teach us to number our days, that we may apply our hearts unto wisdom.", author: "Psalms 90:12", category: "Bible"),
  Quote(id: 359, text: "Where there is no struggle, there is no strength.", author: "Oprah Winfrey", category: "Motivation"),
