  Quote(id: 361, text: "Persistence is to the character of man as carbon is to steel.", author: "Napoleon Hill", category: "Perseverance"),
  Quote(id: 362, text: "Obstacles are those frightful things you see when you take your eyes off your goal.", author: "Henry Ford", category: "Perseverance"),
