  Quote(id: 368, text: "Luck is a dividend of sweat. The more you sweat, the luckier you get.", author: "Ray Kroc", category: "Work"),
  Quote(id: 369, text: "Nothing ever comes to one, that is worth having, except as a result of hard work.", author: "Booker T. Washington", category: "Work"),
  Quote(id: 370, text: "The name of the LORD is a strong tower: the righteous runneth into it, and is safe.", author: "Proverbs 18:10", category: "Bible"),
  Quote(id: 371, text: "Dripping water hollows a stone.", author: "Ovid", category: "Motivation"),
  Quote(id: 372, text: "The secret of success in life is for a man to be ready for his opportunity when it comes.", author: "Benjamin Disraeli", category: "Success"),
