  Quote(id: 407, text: "A dreamer is one who can only find his way by moonlight, and his punishment is that he sees the dawn before the rest of the world.", author: "Oscar Wilde", category: "Dreams"),
  Quote(id: 408, text: "Every morning brings new potential, but if you dwell on the misfortunes of the day before, you tend to overlook tremendous opportunities.", author: "Harvey Mackay", category: "Motivation"),
