  Quote(id: 451, text: "The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.", author: "Psalms 34:18", category: "Bible"),
  Quote(id: 452, text: "Vulnerability is the birthplace of innovation, creativity and change.", author: "Brene Brown", category: "Courage"),
