  Quote(id: 500, text: "You can choose courage or you can choose comfort, but you cannot have both.", author: "Brene Brown", category: "Courage"),
  Quote(id: 501, text: "A dream you dream alone is only a dream. A dream you dream together is reality.", author: "Yoko Ono", category: "Dreams"),
