  Quote(id: 503, text: "The greatest happiness of life is the conviction that we are loved.", author: "Victor Hugo", category: "Happiness"),
  Quote(id: 504, text: "Work is love made visible.", author: "Khalil Gibran", category: "Work"),
  Quote(id: 505, text: "We are a way for the cosmos to know itself.", author: "Carl Sagan", category: "Wisdom"),
