  Quote(id: 549, text: "It's fine to celebrate success but it is more important to heed the lessons of failure.", author: "Bill Gates", category: "Success"),
  Quote(id: 550, text: "Act as if what you do makes a difference. It does.", author: "William James", category: "Action"),
  Quote(id: 551, text: "It is better to do something imperfectly than to do nothing flawlessly.", author: "Robert H. Schuller", category: "Action"),
  Quote(id: 552, text: "What we think, or what we know, or what we believe is, in the end, of little consequence. The only consequence is what we do.", author: "John Ruskin", category: "Action"),
