  Quote(id: 584, text: "May you live all the days of your life.", author: "Jonathan Swift", category: "Life"),
  Quote(id: 585, text: "For the mountains shall depart, and the hills be removed; but my kindness shall not depart from thee, neither shall the covenant of my peace be removed, saith the LORD that hath mercy on thee.", author: "Isaiah 54:10", category: "Bible"),
  Quote(id: 586, text: "If you can keep your head when all about you are losing theirs and blaming it on you.", author: "Rudyard Kipling", category: "Fear"),
  Quote(id: 587, text: "Bravery is the capacity to perform properly even when scared half to death.", author: "Omar Bradley", category: "Courage"),
