  Quote(id: 589, text: "Don't explain your philosophy. Embody it.", author: "Epictetus", category: "Wisdom"),
  Quote(id: 590, text: "It is not because things are difficult that we do not dare; it is because we do not dare that they are difficult.", author: "Seneca", category: "Fear"),
