  Quote(id: 597, text: "Courage is found in unlikely places.", author: "J.R.R. Tolkien", category: "Courage"),
  Quote(id: 598, text: "I press toward the mark for the prize of the high calling of God in Christ Jesus.", author: "Philippians 3:14", category: "Bible"),
  Quote(id: 599, text: "Life can be pulled by goals just as surely as it can be pushed by drives.", author: "Viktor Frankl", category: "Goals"),
  Quote(id: 600, text: "Long-range planning does not deal with future decisions, but with the future of present decisions.", author: "Peter Drucker", category: "Goals"),
  Quote(id: 601, text: "Freedom lies in being bold.", author: "Robert Frost", category: "Fear"),
  Quote(id: 602, text: "Normal day, let me be aware of the treasure you are.", author: "Mary Jean Irion", category: "Life"),
  Quote(id: 603, text: "Wealth consists not in having great possessions, but in having few wants.", author: "Epictetus", category: "Wisdom"),
  Quote(id: 604, text: "Effort only fully releases its reward after a person refuses to quit.", author: "Napoleon Hill", category: "Perseverance"),
  Quote(id: 605, text: "We may encounter many defeats but we must not be defeated.", author: "Maya Angelou", category: "Motivation"),
  Quote(id: 606, text: "I never did a day's work in my life. It was all fun.", author: "Thomas Edison", category: "Work"),
  Quote(id: 607, text: "Even if you're on the right track, you'll get run over if you just sit there.", author: "Will Rogers", category: "Action"),
  Quote(id: 608, text: "He who would learn to fly one day must first learn to stand and walk and run and climb and dance; one cannot fly into flying.", author: "Friedrich Nietzsche", category: "Perseverance"),
  Quote(id: 609, text: "Nothing happens unless first we dream.", author: "Carl Sandburg", category: "Dreams"),
  Quote(id: 610, text: "The difference between successful people and really successful people is that really successful people say no to almost everything.", author: "Warren Buffett", category: "Success"),
  Quote(id: 611, text: "You can't cross the sea merely by standing and staring at the water.", author: "Rabindranath Tagore", category: "Action"),
  Quote(id: 612, text: "Small daily improvements over time lead to stunning results.", author: "Robin Sharma", category: "Goals"),
  Quote(id: 613, text: "Tell me, what is it you plan to do with your one wild and precious life?", author: "Mary Oliver", category: "Life"),
