  Quote(id: 615, text: "I attribute my success to this: I never gave or took any excuse.", author: "Florence Nightingale", category: "Success"),
  Quote(id: 616, text: "In every walk with nature one receives far more than he seeks.", author: "John Muir", category: "Life"),
