  Quote(id: 621, text: "People with goals succeed because they know where they're going.", author: "Earl Nightingale", category: "Goals"),
  Quote(id: 622, text: "Knowing is not enough; we must apply. Willing is not enough; we must do.", author: "Johann Wolfgang von Goethe", category: "Action"),
  Quote(id: 623, text: "Success is dependent on effort.", author: "Sophocles", category: "Success"),
  Quote(id: 624, text: "A professional is someone who can do his best work when he doesn't feel like it.", author: "Alistair Cooke", category: "Work"),
  Quote(id: 625, text: "Winning is a habit. Unfortunately, so is losing.", author: "Vince Lombardi", category: "Success"),
  Quote(id: 626, text: "Without goals, and plans to reach them, you are like a ship that has set sail with no destination.", author: "Fitzhugh Dodson", category: "Goals"),
  Quote(id: 627, text: "Price is what you pay. Value is what you get.", author: "Warren Buffett", category: "Success"),
