  Quote(id: 629, text: "Laughter is the shortest distance between two people.", author: "Victor Borge", category: "Happiness"),
  Quote(id: 630, text: "Worry does not empty tomorrow of its sorrow. It empties today of its strength.", author: "Corrie ten Boom", category: "Fear"),
  Quote(id: 631, text: "What is now proved was once only imagined.", author: "William Blake", category: "Dreams"),
