  Quote(id: 655, text: "Life can only be understood backwards; but it must be lived forwards.", author: "Søren Kierkegaard", category: "Wisdom"),
  Quote(id: 656, text: "We grow great by dreams. All big men are dreamers.", author: "Woodrow Wilson", category: "Dreams"),
  Quote(id: 657, text: "Happiness is not being pained in body or troubled in mind.", author: "Thomas Jefferson", category: "Happiness"),
  Quote(id: 658, text: "The most courageous act is still to think for yourself. Aloud.", author: "Coco Chanel", category: "Courage"),
