  Quote(id: 668, text: "And above all these things put on charity, which is the bond of perfectness.", author: "Colossians 3:14", category: "Bible"),
  Quote(id: 669, text: "Keep true to the dreams of thy youth.", author: "Friedrich Schiller", category: "Dreams"),
