  Quote(id: 698, text: "You can't use up creativity. The more you use, the more you have.", author: "Maya Angelou", category: "Work"),
  Quote(id: 699, text: "A somebody was once a nobody who wanted to and did.", author: "John Burroughs", category: "Goals"),
  Quote(id: 700, text: "Alone we can do so little; together we can do so much.", author: "Helen Keller", category: "Work"),
  Quote(id: 701, text: "True courage is in facing danger when you are afraid.", author: "L. Frank Baum", category: "Courage"),
