  Quote(id: 710, text: "They can because they think they can.", author: "Virgil", category: "Success"),
  Quote(id: 711, text: "And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God.", author: "Romans 12:2", category: "Bible"),
  Quote(id: 712, text: "Absorb what is useful, discard what is useless, and add what is specifically your own.", author: "Bruce Lee", category: "Wisdom"),
  Quote(id: 713, text: "I went to the woods because I wished to live deliberately, to front only the essential facts of life.", author: "Henry David Thoreau", category: "Life"),
  Quote(id: 714, text: "Success is the child of audacity.", author: "Benjamin Disraeli", category: "Success"),
  Quote(id: 715, text: "Failure is the condiment that gives success its flavor.", author: "Truman Capote", category: "Perseverance"),
