  Quote(id: 719, text: "Don't wait for inspiration. It comes while one is working.", author: "Henri Matisse", category: "Work"),
  Quote(id: 720, text: "Fight one more round. When your arms are so tired that you can hardly lift your hands to come on guard, fight one more round.", author: "James J. Corbett", category: "Perseverance"),
  Quote(id: 721, text: "The habit of looking on the best side of every event is worth more than a thousand pounds a year.", author: "Samuel Johnson", category: "Happiness"),
  Quote(id: 722, text: "Be not overcome of evil, but overcome evil with good.", author: "Romans 12:21", category: "Bible"),
  Quote(id: 723, text: "Diligence is the mother of good luck.", author: "Benjamin Franklin", category: "Work"),
  Quote(id: 724, text: "Experience is the name everyone gives to their mistakes.", author: "Oscar Wilde", category: "Wisdom"),
