  Quote(id: 962, text: "Do. Or do not. There is no try.", author: "Yoda", category: "Action"),
  Quote(id: 963, text: "Never give up, for that is just the place and time that the tide will turn.", author: "Harriet Beecher Stowe", category: "Perseverance"),
