  Quote(id: 976, text: "Everyone thinks of changing the world, but no one thinks of changing himself.", author: "Leo Tolstoy", category: "Wisdom"),
  Quote(id: 977, text: "While we are postponing, life speeds by.", author: "Seneca", category: "Wisdom"),
  Quote(id: 978, text: "Everything you can imagine is real.", author: "Pablo Picasso", category: "Dreams"),
  Quote(id: 979, text: "Adopt the pace of nature: her secret is patience.", author: "Ralph Waldo Emerson", category: "Wisdom"),
  Quote(id: 980, text: "Commit thy works unto the LORD, and thy thoughts shall be established.", author: "Proverbs 16:3", category: "Bible"),
