  Quote(id: 992, text: "Dreams are the touchstones of our characters.", author: "Henry David Thoreau", category: "Dreams"),
  Quote(id: 993, text: "Tomorrow is often the busiest day of the week.", author: "Spanish Proverb", category: "Action"),
  Quote(id: 994, text: "And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ's sake hath forgiven you.", author: "Ephesians 4:32", category: "Bible"),
  Quote(id: 995, text: "And ye shall know the truth, and the truth shall make you free.", author: "John 8:32", category: "Bible"),
  Quote(id: 996, text: "By working faithfully eight hours a day you may eventually get to be boss and work twelve hours a day.", author: "Robert Frost", category: "Work"),
  Quote(id: 997, text: "What seem to us bitter trials are often blessings in disguise.", author: "Oscar Wilde", category: "Perseverance"),
  Quote(id: 998, text: "I dream my painting and I paint my dream.", author: "Vincent van Gogh", category: "Dreams"),
  Quote(id: 999, text: "The impediment to action advances action. What stands in the way becomes the way.", author: "Marcus Aurelius", category: "Perseverance"),
